    /// et la valeur du stock revient à son niveau de départ.
    /// </summary>
    [Property(Replay = Graine, MaxTest = NombreDeCas)]
    public void DepotPuisRetrait_LaSommeDeposeeEstRetirable(DepotRetirable depot)
    {
